  "content": "#include "core.cuh"
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <cmath>
#include <algorithm>

int main(int argc, char** argv)
{
    if (argc < 3) { fprintf(stderr, "usage: test1d in.bin out.bin [solver] [limiter] [cfl]\n"); return 1; }
    int solver = argc > 3 ? atoi(argv[3]) : 0, lim = argc > 4 ? atoi(argv[4]) : 0;
    double cfl = argc > 5 ? atof(argv[5]) : 0.8;
    FILE* f = fopen(argv[1], "rb");
    int N, per;
    float gam, tend, L;
    if (fread(&N, 4, 1, f) != 1 || fread(&per, 4, 1, f) != 1 || fread(&gam, 4, 1, f) != 1 || fread(&tend, 4, 1, f) != 1 || fread(&L, 4, 1, f) != 1) return 1;
    std::vector<float> q0((size_t)NV * N);
    if (fread(q0.data(), 4, q0.size(), f) != q0.size()) return 1;
    fclose(f);
    int G = 2, M = N + 2 * G;
    double dx = L / N;
    std::vector<float> U(NV * M), U0(NV * M), F(NV * (N + 1));
    for (int i = 0; i < N; i++) {
        float q[NV], u[NV];
        for (int m = 0; m < NV; m++) q[m] = q0[(size_t)m * N + i];
        prim2cons(q, gam, u);
        for (int m = 0; m < NV; m++) U[m * M + i + G] = u[m];
    }
    auto bc = [&](std::vector<float>& A) {
        for (int g = 0; g < G; g++)
            for (int m = 0; m < NV; m++) {
                A[m * M + g] = per ? A[m * M + N + g] : A[m * M + G];
                A[m * M + N + G + g] = per ? A[m * M + G + g] : A[m * M + N + G - 1];
            }
    };
    auto rhs = [&](std::vector<float>& A, std::vector<float>& T, double dtf, float ch) {
        for (int fi = 0; fi <= N; fi++) {
            float q[4][NV];
            for (int s = 0; s < 4; s++) {
                float u[NV];
                for (int m = 0; m < NV; m++) u[m] = A[m * M + fi + s];
                cons2prim(u, gam, 1e-12f, 1e-12f, q[s]);
            }
            float qL[NV], qR[NV], fl[NV];
            if (lim == 0) plm_face<0>(q[0], q[1], q[2], q[3], qL, qR);
            else if (lim == 1) plm_face<1>(q[0], q[1], q[2], q[3], qL, qR);
            else { for (int m = 0; m < NV; m++) { qL[m] = q[1][m]; qR[m] = q[2][m]; } }
            if (solver == 0) riemann_glm<0>(qL, qR, gam, ch, fl);
            else riemann_glm<1>(qL, qR, gam, ch, fl);
            for (int m = 0; m < NV; m++) F[m * (N + 1) + fi] = fl[m];
        }
        int idx[NV] = {RHO, MX, MY, MZ, EN, BX, BY, BZ, PSI, SC};
        for (int i = 0; i < N; i++)
            for (int m = 0; m < NV; m++) T[idx[m] * M + i + G] += dtf / dx * (F[m * (N + 1) + i] - F[m * (N + 1) + i + 1]);
    };
    double t = 0;
    long steps = 0;
    while (t < tend - 1e-12) {
        bc(U);
        double smax = 0;
        for (int i = G; i < N + G; i++) {
            float u[NV], q[NV];
            for (int m = 0; m < NV; m++) u[m] = U[m * M + i];
            cons2prim(u, gam, 1e-12f, 1e-12f, q);
            float b2 = q[5] * q[5] + q[6] * q[6] + q[7] * q[7];
            smax = std::max(smax, (double)(fabsf(q[1]) + cfast(q[0], q[4], q[5], b2, gam)));
        }
        double dt = std::min(cfl * dx / smax, (double)tend - t);
        float ch = smax;
        U0 = U;
        rhs(U0, U, dt, ch);
        bc(U);
        for (size_t a = 0; a < U.size(); a++) U[a] = 0.5f * (U0[a] + U[a]);
        std::vector<float> U1 = U;
        for (size_t a = 0; a < U.size(); a++) U1[a] = 2.f * U[a] - U0[a];
        bc(U1);
        rhs(U1, U, 0.5 * dt, ch);
        t += dt;
        steps++;
    }
    FILE* o = fopen(argv[2], "wb");
    fwrite(&N, 4, 1, o);
    for (int m = 0; m < NV; m++)
        for (int i = 0; i < N; i++) {
            float u[NV], q[NV];
            for (int mm = 0; mm < NV; mm++) u[mm] = U[mm * M + i + G];
            cons2prim(u, gam, 1e-12f, 1e-12f, q);
            fwrite(&q[m], 4, 1, o);
        }
    fclose(o);
    fprintf(stderr, "N=%d steps=%ld t=%.4f\n", N, steps, t);
    return 0;
}
